-- VS Code transparency
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.window_rule({
    match = {
        class = "^(code-url-handler)$",
    },
    opacity = "0.95 0.85",
})

hl.window_rule({
    match = {
        class = "^(Code)$",
    },
    opacity = "0.95 0.85",
})

hl.window_rule({
    match = {
        class = "^(code)$",
    },
    opacity = "0.95 0.85",
})

hl.window_rule({
    match = {
        class = "^(VSCodium)$",
    },
    opacity = "0.95 0.85",
})

-- Dolphin
hl.window_rule({
    match = {
        class = "^(org.kde.dolphin)$",
    },
    opacity = "0.9 0.9",
})

-- ── Layer blur ───────────────────────────────────────────────
-- Without these, a translucent bar is just a flat tinted fill over the
-- wallpaper -- the wallpaper shows through undistorted, which reads as
-- tinted plastic. `blur on` is what actually makes it glass.
-- ignore_alpha skips blurring pixels below that alpha, so the fully
-- transparent parts of the waybar surface (everything outside the
-- island pill) don't get a blurred rectangle painted behind them.
hl.layer_rule({
    match = { namespace = "waybar" },
    blur = true,
    ignore_alpha = 0.15,
})

-- eww popups -- same glass treatment as the bar
hl.layer_rule({
    match = { namespace = "calendar-panel" },
    blur = true,
})

hl.layer_rule({
    match = { namespace = "calendar-panel" },
    ignore_alpha = 0.15,
})

-- Notifications get the same glass as the bar. dunst paints a flat fill,
-- so without a blur behind it a toast reads as a solid card while every
-- other surface on the desktop is glass.
hl.layer_rule({
    match = { namespace = "notifications" },
    blur = true,
    ignore_alpha = 0.15,
})

-- rofi no longer draws the launcher -- that moved into eww, and on
-- 2026-09-16 into the island (quickshell/SearchPanel.qml). These stay
-- because rofi is still installed and anything else that calls it should
-- still look right.
hl.layer_rule({
    match = { namespace = "rofi" },
    blur = true,
    ignore_alpha = 0,
})

-- The session menu is NOT blurred. It used to be, and that was too much:
-- blur is a global kernel here (size 7, passes 3) tuned for a 38px bar
-- you look through, and Hyprland 0.54 has no per-layer strength -- the
-- layerrule is on/off. Behind wlogout's dark scrim that kernel erased the
-- desktop into a flat wall. A full-screen surface does not need to read
-- as glass; the scrim in wlogout/style.css (0.72) does the isolating and
-- the desktop stays recognisable behind it.
--
-- NOTE for whoever re-adds it: the namespace is `logout_dialog`, NOT
-- `wlogout` -- wlogout names its layer surface after the dialog, not
-- after the binary. Verified with `hyprctl layers` while it was open;
-- `match:namespace wlogout` matched nothing and failed silently, which is
-- how every wrong layerrule fails.
